// Nekomachi service worker (generated by build.py; __VERSION__ changes on every build).
// The page is network-first, so a new deploy always shows up; sounds, music and the
// three.js libraries are cache-first, so repeat visits start instantly and work offline.
const CACHE = 'nekomachi-__VERSION__';
const PRECACHE = ['/', '/manifest.webmanifest', '/icon-192.png', '__RUNTIME__'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('nekomachi-') && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

const isAsset = url =>
  (url.origin === self.location.origin && /^\/(audio|vendor|assets)\/|\.(png|webmanifest)$/.test(url.pathname)) ||
  url.href.startsWith('https://cdn.jsdelivr.net/npm/three@0.147.0/');

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.hostname === 'api.tanmaybohra.com') return;   // leaderboard: always live

  if (req.mode === 'navigate') {
    e.respondWith(
      fetch(req)
        .then(res => { const copy = res.clone(); caches.open(CACHE).then(c => c.put('/', copy)); return res; })
        .catch(() => caches.match('/')),
    );
    return;
  }
  if (isAsset(url)) {
    e.respondWith(
      caches.match(req).then(hit => hit || fetch(req).then(res => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
        return res;
      })),
    );
  }
});
